enum MenuCommand
{
  MENUCMD_NONE = 0,
  MENUCMD_SELECT,
  MENUCMD_START,
  MENUCMD_UP,
  MENUCMD_DOWN,
  MENUCMD_LEFT,
  MENUCMD_RIGHT,
  MENUCMD_CROSS,
  MENUCMD_TRIANGLE,
  MENUCMD_SQUARE,
  MENUCMD_CIRCLE,
  MENUCMD_L1,
  MENUCMD_R1,
  MENUCMD_L2,
  MENUCMD_R2
};

class MenuEntryLabel
{
  int entry_data;

public:
  virtual ~MenuEntryLabel() {}
  virtual void OnButtonPress(int);
};

class MenuEntryFloatEdit : public MenuEntryLabel
{
  float *tfloat;

protected:
  float lo;
  float hi;
  float step;
  char *format;

public:
  virtual ~MenuEntryFloatEdit() {}
  virtual void OnButtonPress(int buttonid);
  virtual void SetValue(float n) { *tfloat = n; }
  virtual float GetValue() { return tfloat ? *tfloat : 0; }
  void FixValue();
};

void MenuEntryFloatEdit::OnButtonPress(int buttonid)
{
  switch (buttonid)
  {
    case MENUCMD_LEFT:
      SetValue(GetValue() - step);
      FixValue();
      break;
    case MENUCMD_RIGHT:
      SetValue(GetValue() + step);
      FixValue();
      break;
    case MENUCMD_L1:
      SetValue(GetValue() - step * 10);
      FixValue();
      break;
    case MENUCMD_R1:
      SetValue(GetValue() + step * 10);
      FixValue();
      break;
    case MENUCMD_L2:
      SetValue(GetValue() - step * 100);
      FixValue();
      break;
    case MENUCMD_R2:
      SetValue(GetValue() + step * 100);
      FixValue();
      break;
    default:
      MenuEntryLabel::OnButtonPress(buttonid);
  }
}
